game.import("play", function () {
	return {
		name: "boss",
		init() {
			if (get.mode() === "tafang") {
				return;
			}
			let storage = localStorage.getItem("boss_storage_playpackconfig");
			try {
				storage = JSON.parse(storage) || {};
			} catch (e) {
				storage = {};
			}
			if (get.mode() !== "boss") {
				lib.characterPack.boss = storage.boss || {};
				for (const i in lib.characterPack.boss) {
					lib.characterPack.boss[i].img = `image/mode/boss/character/${i}.jpg`;
					lib.character[i] = lib.characterPack.boss[i];
					if (typeof lib.character[i][2] !== "number" && (typeof lib.character[i][2] !== "string" || lib.character[i][2].indexOf("/") === -1)) {
						lib.character[i][2] = Infinity;
					}
					if (!lib.config.boss_enableai_playpackconfig) {
						lib.config.forbidai.push(i);
					}
				}
			}
			let list2 = storage.versus || {};
			if (get.mode() !== "versus" || get.config("versus_mode") !== "jiange") {
				lib.characterPack.jiange = list2;
				for (const i in lib.characterPack.jiange) {
					lib.characterPack.jiange[i].img = `image/mode/versus/character/${i}.jpg`;
					lib.character[i] = lib.characterPack.jiange[i];
					if (typeof lib.character[i][2] !== "number") {
						lib.character[i][2] = Infinity;
					}
					if (!lib.config.boss_enableai_playpackconfig) {
						lib.config.forbidai.push(i);
					}
				}
				lib.characterIntro.boss_liedixuande = lib.characterIntro.liubei;
				lib.characterIntro.boss_gongshenyueying = lib.characterIntro.huangyueying;
				lib.characterIntro.boss_tianhoukongming = lib.characterIntro.shen_zhugeliang;
				lib.characterIntro.boss_yuhuoshiyuan = lib.characterIntro.pangtong;
				lib.characterIntro.boss_qiaokuijunyi = lib.characterIntro.zhanghe;
				lib.characterIntro.boss_jiarenzidan = lib.characterIntro.caozhen;
				lib.characterIntro.boss_duanyuzhongda = lib.characterIntro.simayi;
				lib.characterIntro.boss_juechenmiaocai = lib.characterIntro.xiahouyuan;
				lib.characterIntro.boss_kumuyuanrang = lib.characterIntro.xiahoudun;
				lib.characterIntro.boss_baijiwenyuan = lib.characterIntro.zhangliao;
				lib.characterIntro.boss_yihanyunchang = lib.characterIntro.guanyu;
				lib.characterIntro.boss_fuweizilong = lib.characterIntro.zhaoyun;
				lib.characterIntro.boss_lvbu1 = lib.characterIntro.lvbu;
				lib.characterIntro.boss_lvbu2 = lib.characterIntro.lvbu;
				lib.characterIntro.boss_lvbu3 = lib.characterIntro.lvbu;
			} else if (_status.mode !== "jiange") {
				for (const i in list2) {
					lib.character[i] = list2[i];
					if (!lib.config.boss_enableai_playpackconfig) {
						lib.config.forbidai.push(i);
					}
				}
			}
			let list = storage.translate || {};
			list.boss_character_config = "挑战武将";
			list.jiange_character_config = "剑阁武将";

			for (const i in list) {
				lib.translate[i] ||= list[i];
			}
		},
		arenaReady() {
			if (get.mode() === "tafang") {
				return;
			}
			let storage = localStorage.getItem("boss_storage_playpackconfig");
			try {
				storage = JSON.parse(storage) || {};
			} catch (e) {
				storage = {};
			}
			if (!storage.translate) {
				storage.translate = {};
			}
			const loadversus = function () {
				if (get.mode() !== "versus") {
					game.loadModeAsync("versus", function (mode) {
						for (const i in mode.translate) {
							lib.translate[i] ||= mode.translate[i];
							storage.translate[i] = mode.translate[i];
						}
						for (const i in mode.skill) {
							if (lib.skill[i]) {
								console.log(i);
							}
							if (i !== "versus_ladder") {
								lib.skill[i] = mode.skill[i];
							}
						}
						for (const ii in mode.skill) {
							if (ii !== "versus_ladder") {
								game.finishSkill(ii);
							}
						}
						storage.versus = {};
						for (const i in mode.jiangeboss) {
							if (mode.jiangeboss[i].isBossAllowed) {
								storage.versus[i] = mode.jiangeboss[i];
							}
						}
						localStorage.setItem("boss_storage_playpackconfig", JSON.stringify(storage));
					});
				} else {
					localStorage.setItem("boss_storage_playpackconfig", JSON.stringify(storage));
				}
			};
			if (get.mode() !== "boss") {
				game.loadModeAsync("boss", function (mode) {
					for (const i in mode.translate) {
						lib.translate[i] ||= mode.translate[i];
						storage.translate[i] = mode.translate[i];
					}
					for (const i in mode.skill) {
						if (lib.skill[i]) {
							console.log(i);
						}
						lib.skill[i] = mode.skill[i];
					}
					for (const ii in mode.skill) {
						if (ii !== "versus_ladder") {
							game.finishSkill(ii);
						}
					}
					storage.boss = {};
					for (const i in mode.characterPack.mode_boss) {
						if (mode.characterPack.mode_boss[i].isBossAllowed) {
							storage.boss[i] = mode.characterPack.mode_boss[i];
						}
					}
					loadversus();
				});
			} else {
				loadversus();
			}
		},
	};
})

game.loadModeAsync("versus", function (mode) {
						for (const i in mode.translate) {
							lib.translate[i] ||= mode.translate[i];
							storage.translate[i] = mode.translate[i];
						}
						for (const i in mode.skill) {
							if (lib.skill[i]) {
								console.log(i);
							}
							if (i !== "versus_ladder") {
								lib.skill[i] = mode.skill[i];
							}
						}
						for (const ii in mode.skill) {
							if (ii !== "versus_ladder") {
								game.finishSkill(ii);
							}
						}
						storage.versus = {};
						for (const i in mode.jiangeboss) {
							if (mode.jiangeboss[i].isBossAllowed) {
								storage.versus[i] = mode.jiangeboss[i];
							}
						}
						localStorage.setItem("boss_storage_playpackconfig", JSON.stringify(storage));
					})

game.loadModeAsync("boss", function (mode) {
					for (const i in mode.translate) {
						lib.translate[i] ||= mode.translate[i];
						storage.translate[i] = mode.translate[i];
					}
					for (const i in mode.skill) {
						if (lib.skill[i]) {
							console.log(i);
						}
						lib.skill[i] = mode.skill[i];
					}
					for (const ii in mode.skill) {
						if (ii !== "versus_ladder") {
							game.finishSkill(ii);
						}
					}
					storage.boss = {};
					for (const i in mode.characterPack.mode_boss) {
						if (mode.characterPack.mode_boss[i].isBossAllowed) {
							storage.boss[i] = mode.characterPack.mode_boss[i];
						}
					}
					loadversus();
				})

game.import("play", function () {
	return {
		name: "cardpile",
		arenaReady() {
			const data = {
				total: 160,
				sha: {
					diamond: 6,
					club: 14,
					heart: 3,
					spade: 7,
				},
				huosha: {
					diamond: 2,
					heart: 3,
				},
				leisha: {
					spade: 5,
					club: 4,
				},
				shan: {
					heart: 6,
					diamond: 18,
				},
				jiu: {
					diamond: 1,
					spade: 2,
					club: 2,
				},
				tao: {
					heart: 9,
					diamond: 3,
				},
				wanjian: {
					heart: 1,
				},
				nanman: {
					spade: 2,
					club: 1,
				},
				guohe: {
					spade: 3,
					club: 2,
					heart: 1,
				},
				shunshou: {
					spade: 3,
					diamond: 2,
				},
				wuxie: {
					heart: 2,
					diamond: 1,
					spade: 2,
					club: 2,
				},
				tiesuo: {
					spade: 2,
					club: 4,
				},
			};
			const rand = function () {
				return Math.ceil(Math.random() * 13);
			};
			const getn = function (i, j) {
				return Math.round(data[i][j] * parseFloat(lib.config[`cardpile_${i}_playpackconfig`]));
			};
			let num = 0;
			for (const i in data) {
				for (const j in data[i]) {
					num += getn(i, j);
				}
			}
			let dn = (num * (lib.card.list.length - data.total)) / (data.total - num);
			if (dn > 1000) {
				dn = 1000;
			}
			if (dn > 0) {
				for (const i in data) {
					for (const j in data[i]) {
						let n = Math.round((dn * getn(i, j)) / num);
						while (n--) {
							switch(i) {
								case "huosha":
									lib.card.list.push([j, rand(), "sha", "fire"]);
									break;
								case "leisha":
									lib.card.list.push([j, rand(), "sha", "thunder"]);
									break;
								default:
									lib.card.list.push([j, rand(), i]);
							}
						}
					}
				}
			}
		},
	};
})

game.import("play", function () {
	return {
		name: "coin",
		init() {
			if (lib.config.mode !== "chess" || get.config("chess_mode") !== "leader") {
				_status.coin = 0;
			}
		},
		arenaReady() {
			if (_status.video || _status.connectMode) {
				return;
			}
			if (lib.config.mode !== "chess" || get.config("chess_mode") !== "leader") {
				var str;
				if (lib.config.coin_display_playpackconfig === "text") {
					str = "<span>" + lib.config.coin + "</span><span>金</span>";
				} else {
					str = '<span style="position:absolute">㉤</span><span style="margin-left:18px;font-family:xinwei;line-height:10px">' + lib.config.coin + "</span>";
				}
				if (lib.config.coin_canvas_playpackconfig) {
					ui.window.classList.add("canvas_top");
				}
				ui.coin = ui.create.system(str, null, true);
				if (lib.config.snowFall) {
					game.haveFun.list.snow.bought = true;
					setTimeout(function () {
						game.haveFun.snow();
					}, 500);
				}
				lib.setPopped(ui.coin, function () {
					var uiintro = ui.create.dialog("hidden");
					uiintro.classList.add("coin_menu");
					uiintro.add("商店");
					uiintro.listen(function (e) {
						e.stopPropagation();
					});
					var clickBuy = function () {
						if (this.innerHTML === "停止") {
							game.haveFun[this.name + "Stop"]();
						} else if (this.innerHTML === "开始") {
							game.haveFun[this.name]();
						} else if (this.innerHTML.indexOf("金") !== -1) {
							if (lib.config.coin >= this.content.cost) {
								this.content.bought = true;
								game.changeCoin(-this.content.cost);
								game.haveFun[this.name]();
								if (this.content.onbuy) {
									this.content.onbuy.call(this);
								}
							} else {
								return;
							}
						}
						ui.click.window();
					};
					for (var i in game.haveFun.list) {
						var item = game.haveFun.list[i];
						uiintro.add('<div class="coin_buy">' + item.name + '<div class="menubutton">' + item.cost + "金</span></div></div>");
						var buy = uiintro.content.lastChild.lastChild.lastChild;
						if (lib.config.coin < item.cost && !item.bought) {
							buy.classList.add("disabled");
						}
						if (item.bought) {
							if (item.running) {
								buy.innerHTML = "停止";
								if (item.control) {
									var node = item.control();
									if (node) {
										buy.parentNode.appendChild(node, buy);
									}
								}
							} else {
								buy.innerHTML = "开始";
							}
						}
						buy.name = i;
						buy.content = item;
						buy.listen(clickBuy);
					}

					if (!game.phaseNumber && !game.online) {
						uiintro.add("下注");
						uiintro.add('<div class="coin_buy">本局获胜<div class="menubutton">20金</span></div></div>');
						var bet = uiintro.content.lastChild.lastChild.lastChild;
						bet.listen(function () {
							if (_status.betWin) {
								return;
							}
							_status.betWin = true;
							game.changeCoin(-20);
							this.innerHTML = "已下注";
						});
						if (_status.betWin) {
							bet.innerHTML = "已下注";
						}
					} else if (_status.betWin) {
						uiintro.add("下注");
						uiintro.add('<div class="coin_buy">本局获胜<div class="menubutton">已下注</span></div></div>');
					}
					uiintro.classList.add("noleave");
					return uiintro;
				}, 220, 400);
			}
		},

		game: {
			changeCoin(num, toast, audio) {
				if (typeof num === "number" && ui.coin) {
					if (num !== 0 && toast !== false) {
						ui.create.toast(`${num > 0 ? "获得" : "花费"}&nbsp;${Math.abs(num)}&nbsp;金币`);
					}
					if (audio !== false) {
						game.playAudio("effect", num > 0 ? "coin" : "coin_cost");
					}
					game.saveConfig("coin", lib.config.coin + num);
					var str;
					if (lib.config.coin_display_playpackconfig === "text") {
						str = "<span>" + lib.config.coin + "</span><span>金</span>";
					} else {
						str = '<span style="position:absolute">㉤</span><span style="margin-left:18px;font-family:xinwei;line-height:10px">' + lib.config.coin + "</span>";
					}
					ui.coin.innerHTML = str;
				}
			},
			haveFun: {
				list: {
					firework: {
						name: "烟花",
						cost: 50,
					},
					snow: {
						name: "下雪",
						cost: 20,
						size: "large",
						control() {
							var size = ui.create.div(".menubutton");
							if (game.haveFun.list.snow.size === "small") {
								size.innerHTML = "大雪";
							} else {
								size.innerHTML = "小雪";
							}
							size.listen(game.haveFun.snowSize);
							return size;
						},
					},
					star: {
						name: "星云",
						cost: 10,
					},
					blink: {
						name: "闪烁",
						cost: 10,
					},
				},
				alwaysSnow() {
					game.saveConfig("snowFall", !lib.config.snowFall);
					game.reload();
				},
				blink() {
					if (game.haveFun.list.blink.running) {
						return;
					}
					game.haveFun.list.blink.running = true;
					if (game.haveFun.blinkLoop) {
						game.haveFun.blinkLoop();
					} else {
						var canvas = document.createElement("canvas");
						ui.window.appendChild(canvas);
						canvas.classList.add("fun");
						canvas.style.zIndex = 20;
						var ctx = canvas.getContext("2d");

						//Make the canvas occupy the full page
						var W = ui.window.offsetWidth,
							H = ui.window.offsetHeight;
						canvas.width = W;
						canvas.height = H;
						lib.onresize.push(() => {
							var W = ui.window.offsetWidth,
								H = ui.window.offsetHeight;
							canvas.width = W;
							canvas.height = H;
						});

						var particles = [];
						var mouse = {};

						//Lets create some particles now
						var particle_count = 25;

						//finally some mouse tracking
						ui.window.addEventListener("mousemove", function (e) {
							//since the canvas = full page the position of the mouse
							//relative to the document will suffice
							mouse.x = e.pageX / game.documentZoom;
							mouse.y = e.pageY / game.documentZoom;
						});
						ui.window.addEventListener("touchmove", function (e) {
							mouse.x = e.touches[0].clientX / game.documentZoom;
							mouse.y = e.touches[0].clientY / game.documentZoom;
						});
						class particle {
							constructor() {
								// speed, life, location, life, colors
								// speed.x range = -2.5 to 2.5
								// speed.y range = -15 to -5 to make it move upwards
								// lets change the Y speed to make it look like a flame
								this.speed = {
									x: -2.5 + Math.random() * 5,
									y: -5 + Math.random() * 10,
								};
								this.speed.x /= 4;
								this.speed.y /= 4;

								// location = mouse coordinates
								// Now the flame follows the mouse coordinates
								if (mouse.x && mouse.y) {
									this.location = {
										x: mouse.x,
										y: mouse.y
									};
								} else {
									this.location = {
										x: W / 2,
										y: H / 2
									};
								}

								// radius range = 10-30
								this.radius = 10 + Math.random() * 20;
								// life range = 20-30
								this.radius /= 4;
								this.life = 20 + Math.random() * 10;
								this.life *= 4;
								this.remaining_life = this.life;

								// colors
								this.r = Math.round(Math.random() * 255);
								this.g = Math.round(Math.random() * 255);
								this.b = Math.round(Math.random() * 255);
							}
						}
						for (var i = 0; i < particle_count; i++) {
							particles.push(new particle());
						}

						var draw = function () {
							if (!game.haveFun.list.blink.running) {
								canvas.width = W;
								canvas.height = H;
								return;
							}
							ctx.clearRect(0, 0, W, H);
							//Painting the canvas black
							//Time for lighting magic
							//particles are painted with "lighter"
							//In the next frame the background is painted normally without blending to the
							//previous frame
							ctx.globalCompositeOperation = "lighter";

							for (var i = 0; i < particles.length; i++) {
								var p = particles[i];
								ctx.beginPath();
								//changing opacity according to the life.
								//opacity goes to 0 at the end of life of a particle
								p.opacity = Math.round((p.remaining_life / p.life) * 100) / 100;
								//a gradient instead of white fill
								var gradient = ctx.createRadialGradient(p.location.x, p.location.y, 0, p.location.x, p.location.y, p.radius);
								gradient.addColorStop(0, "rgba(" + p.r + ", " + p.g + ", " + p.b + ", " + p.opacity + ")");
								gradient.addColorStop(0.5, "rgba(" + p.r + ", " + p.g + ", " + p.b + ", " + p.opacity + ")");
								gradient.addColorStop(1, "rgba(" + p.r + ", " + p.g + ", " + p.b + ", 0)");
								ctx.fillStyle = gradient;
								ctx.arc(p.location.x, p.location.y, p.radius, Math.PI * 2, false);
								ctx.fill();

								//lets move the particles
								p.remaining_life--;
								p.radius -= 0.2;
								p.location.x += p.speed.x;
								p.location.y += p.speed.y;

								//regenerate particles
								if (p.remaining_life < 0 || p.radius < 0) {
									//a brand new particle replacing the dead one
									particles[i] = new particle();
								}
							}
							requestAnimationFrame(draw);
						};

						draw();
						game.haveFun.blinkLoop = draw;
