					return !target.hasSkill('liyutang');
				},
				//range:{global:1},
				content:function(){
					target.$gain2(cards);
					target.storage.liyutang=card;
					target.storage.liyutang_markcount=2;
					target.addSkill('liyutang');
				},
				ai:{
