						editor.appendChild(textarea);
						node.textarea = textarea;
						lib.setScroll(textarea);
					}
					node.textarea.value = node.code;
				} else {
					let aceReady = function () {
						ui.window.appendChild(node);
						let mirror = window.CodeMirror(editor, {
							value: node.code,
							mode: 'javascript',
							lineWrapping: !lib.config.touchscreen && lib.config.mousewheel,
							lineNumbers: true,
							indentUnit: 4,
							autoCloseBrackets: true,
							theme: 'mdn-like'
						});
						lib.setScroll(editor.querySelector('.CodeMirror-scroll'));
						node.aced = true;
						node.editor = mirror;
					};
					if (!window.ace) {
						lib.init.js(lib.assetURL + 'game', 'codemirror', aceReady);
						lib.init.css(lib.assetURL + 'layout/default', 'codemirror');
					} else aceReady();
				}
			}
		},
		copyCf: {
			name: '一键复制修改的技能威胁度',
			clear: true,
			onclick: function () {
				let map = lib.config.extension_AI优化_cf || {};
				let txt = '';
				for (let i in map) {
					txt += '\r	"' + i + '": ' + map[i] + ',';
				}
				const textarea = document.createElement('textarea');
				textarea.setAttribute('readonly', 'readonly');
				textarea.value = txt;
				document.body.appendChild(textarea);
				textarea.select();
				if (document.execCommand('copy')) {
					document.execCommand('copy');
					alert('已成功复制到剪切板');
				} else alert('复制失败');
				document.body.removeChild(textarea);
			}
		},
		clearCf: {
			name: '清空修改的技能威胁度',
			clear: true,
			onclick: function () {
				let xs = 0;
				for (let i in lib.config.extension_AI优化_cf) {
					xs++;
				}
				if (confirm('您确定要清空所有通过上述功能修改的技能威胁度（共' + xs + '项）？')) {
					game.saveExtensionConfig('AI优化', 'cf', {});
					alert('清除成功');
				}
			}
		},
		bd7: {
			name: '<hr>',
			clear: true
		},
	},
	help: {},
	package: {
		character: {
			character: {},
			translate: {}
		},
		card: {
			card: {},
			translate: {},
			list: []
		},
		skill: {
			skill: {},
			translate: {}
		},
		intro: '<font color=#00FFFF>建立者</font>：<br>&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp柚子丶奶茶丶猫以及面具<br>&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp翩翩浊世许公子<br>&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp157<br><font color=#00FFFF>现更者</font>：<br>&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp157<br><font color=#00FFFF>特别鸣谢</font>：<br>&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp寰宇星城(插件功能)<br>&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp༺ཌༀཉི梦ღ沫ღ惜༃ༀ(工具人)<br>&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp萌新（转型中）(本体优化)<br>&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp😁呲牙哥！(扩展宣传)<br>&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp读书人(扩展宣传)<br>&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp幸运女神在微笑(扩展宣传)<br>&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp&nbspAurora(代码参考)<br>&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp蓝色火鸡(代码提供)<br>&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp呓如惑(测试反馈)<br><font color=#00FFFF>当前版本号</font>：<font color=#FFFF00>1.2.6</font><br><font color=#00FFFF>支持本体版本号</font>：<font color=#FFFF00>1.10.1</font><br><font color=#00FFFF>更新日期</font>：23年<font color=#00FFB0>10</font>月<font color=#FFFF00>20</font>日<font color=fire> 0</font>时<br>',
		author: '',
		diskURL: '',
		forumURL: '',
		version: '1.2.6'
	},
	files: {character: [], card: [], skill: []}
}})

