                if (this.shrink) {
                    this.shrink.removeEventListener('scroll', this.onscroll);
                }

                if (this.element && this.expand && this.shrink) {
                    this.element.removeChild(this.expand);
                    this.element.removeChild(this.shrink);
                }

                this.events = null;
                this.expand = null;
                this.shrink = null;
                this.element = null;
            };

