				getRandom: function (min, max) {
			if (min == null) {
				min = -2147483648;
			}

			if (max == null) {
				max = 2147483648;
			}

			if (min > max) {
				min = min + max;
				max = min - max;
				min = min - max;
			}

			var diff = 0;
			if (min < 0) {
				diff = min;
				min = 0;
				max -= diff;
			}

			return Math.floor(Math.random() * (max + 1 - min)) + min + diff;
		},
