          var double_hp;
          if (_status.connectMode || get.mode() == 'single') {
            double_hp = 'pingjun';
          }
          else {
            double_hp = get.config('double_hp');
          }
          switch (double_hp) {
            case 'pingjun': {
              this.maxHp = Math.floor((maxHp1 + maxHp2) / 2);
              this.hp = Math.floor((hp1 + hp2) / 2);
              this.singleHp = ((maxHp1 + maxHp2) % 2 === 1);
              break;
