            this.name = to;
          }
          if (smooth) this.smoothAvatar(true);
          this.node.avatar2.setBackground(to, 'character');
          this.node.name2.innerHTML = get.prefixBoldName(to,'character');
          if (window.qhly_newDynamicExt) {
