      game.qhly_deepClone = function (obj, newObj) {
        var newObj = newObj || {};
        for (let key in obj) {
          if (Array.isArray(obj[key])) {
            newObj[key] = [...obj[key]];
          } else if (typeof obj[key] == 'object' && obj[key] != null) {
            if (obj[key] === obj) {
              newObj[key] = newObj;
              continue;
            }
            newObj[key] = {};
            game.qhly_deepClone(obj[key], newObj[key]);
          } else {
            newObj[key] = obj[key]
          }
        }
        return newObj;
      }
