        if (!lib.config.qhly_keymark) return null;
        if (lib.config.qhly_keymark.length == 0) return null;
        var pairs = lib.config.qhly_keymark.split(";");
        var obj = {};
        for (var pair of pairs) {
          var us = pair.split(":");
          if (us[0] && us[1] && us[0].length && us[1].length) {
            obj[us[0]] = us[1];
          }
        }
        return obj;
