      lib.qhly_keyMark = function (str) {
        if (!lib.config.qhly_keymarkopen) return str;
        var obj = lib.qhly_getSkillKeyWordColorList();
        if (!obj) return str;
        for (var k in obj) {
          var v = obj[k];
          if (k.indexOf("#") == 0) {
            var k2 = k.slice(1);
            str = str.replaceAll(k2, "<b style='color:" + v + "'>" + k2 + "</b>");
          } else {
            str = str.replace(k, "<b style='color:" + v + "'>" + k + "</b>");
          }
        }
        return str;
