        var identity = get.mode() == 'guozhan' ? player.group : player.identity;
        if (!identity) {
          identity = "未知身份";
        } else {
          identity = get.translation(identity + '2');
        }
        var wlr = recordMode[identity];
        if (!wlr) {
          wlr = {};
          recordMode[identity] = wlr;
        }
        if (win === true) {
          if (!wlr.win) {
            wlr.win = 0;
          }
          wlr.win++;
        } else if (win === false) {
          if (!wlr.lose) {
