          skinOrder: function (view) {
            if (view.skinOrder === undefined) {
              for (var i = 0; i < this.skinViews.length; i++) {
                this.skinViews[i].skinOrder = i;
              }
            }
            return view.skinOrder;
          },
          angleLocationOf: function (view) {
