            if (this.skins.length <= 8) {
              while (newCur < -180) {
                newCur += 360;
              }
              while (newCur > 180) {
                newCur -= 360;
              }
            } else {
              if (newCur > this.maxAngle()) {
                newCur = this.maxAngle();
              } else if (newCur < this.minAngle()) {
                newCur = this.minAngle();
              }
