                  if (viewSkill.contains(tskill)) continue;
                  var info = get.info(tskill);
                  if (!info) continue;
                  if (!lib.translate[tskill]) continue;
                  if (info.popup === false) continue;
                  if (info.nopop === true) continue;
                  viewSkill.add(tskill);
                  tempSkill.add(tskill);
                }
