                        } else {
                          for (var s of list) {
                            lib.config.autoskilllist.remove(s);
                          }
                        }
                        game.saveConfig('autoskilllist', lib.config.autoskilllist);
                      };
                    }
                  })(skill);
                }
              }
              game.qhly_changeViewPageSkin('skill', this.pageView);
              this.inited = true;
            }
