              if (ctitle && ctitle[0] === '#' && ctitle.length >= 2) {
                switch (ctitle[1]) {
                  case 'r':
                    subView.characterTitle.style.color = 'red';
                    break;
                  case 'g':
                    subView.characterTitle.style.color = 'green';
                    break;
                  case 'p':
