                  } else if (currentViewSkin.isLolBigLayout) {
                    hptext.style.top = "44px";
                  }
                  subView.hp.appendChild(hptext);
                  hptext.innerHTML = "×" + (currentViewSkin.isLolBigLayout ? "<br>" : "") + hp;
                }
              }
            } else if (typeof hp == 'string') {
