            if (mp === null || mp === undefined) {
              subView.mp.hide();
            } else {
              subView.mp.show();
              subView.mpText.innerHTML = mp + "";
            }
          }
        };
        refreshView(state, subView);
        game.qhly_changeViewSkin(subView);
        showPage(page);
      };
