                        var imageData = context.getImageData(0, 0, 50, 50).data;
                        for (var index = 3; index < 100; index += 4) {
                            if (imageData[index] != 255) {
                                isAlphaBackground++;
                                if (isAlphaBackground>=25) {
                                    resolve();
                                    break;
