                function numtoroma(num) {
                    switch (num) {
                        case 1:
                            return 'Ⅰ';
                        case 2:
                            return 'Ⅱ';
                        case 3:
                            return 'Ⅲ';
                        case 4:
                            return 'Ⅳ';
                        case 5:
                            return 'Ⅴ';
                        case 6:
                            return 'Ⅵ';
                        default:
                            return null;
                    }
                }

                function getName_排位 (num) {
                    let xingxingNum; //用来转化为罗马数字
                    let outname; //段位名字
                    let duannum;
                    let outroma; //段位等级
                    let xxnum; //小星星
                    let xxnumlim; //星星上限
                    if (num < 1) {
                        outname = '青铜';
                        xingxingNum = 3;
                        xxnum = 0;
                        xxnumlim = 2;
                        duannum = 1;
                    } else if (num < 7) {
                        outname = '青铜';
                        xingxingNum = 3 - Math.floor((num - 1) / 2);
                        xxnum = (num - 1) % 2 + 1; //段位星星数
                        xxnumlim = 2;
                        duannum = 1;
                    } else if (num < 19) {
                        outname = '白银';
                        xingxingNum = 3 - Math.floor((num - 7) / 4);
                        xxnum = (num - 7) % 4 + 1;
                        xxnumlim = 4;
                        duannum = 2;
                    } else if (num < 44) {
                        outname = '黄金';
                        xingxingNum = 5 - Math.floor((num - 19) / 5);
                        xxnum = (num - 19) % 5 + 1;
                        xxnumlim = 5;
                        duannum = 3;
                    } else if (num < 69) {
                        outname = '翡翠';
                        xingxingNum = 5 - Math.floor((num - 44) / 5);
                        xxnum = (num - 44) % 5 + 1;
                        xxnumlim = 5;
                        duannum = 4;
                    } else if (num < 99) {
                        outname = '大师';
                        xingxingNum = 6 - Math.floor((num - 69) / 5);
                        xxnum = (num - 69) % 5 + 1;
                        xxnumlim = 5;
                        duannum = 5;
                    } else {
                        outname = '传说';
                        xingxingNum = 1;
                        xxnum = num - 98;
                        xxnumlim = 1000;
                        duannum = 6;
                    }
                    outroma = numtoroma(xingxingNum);
                    return [outname + outroma, xxnum, xxnumlim, duannum] //段位名称，星星数量，星星上限，段位数（1~6）
                }
