            // 任务队列类
            class TaskQueue {
                constructor(interval = 250) {
                    this.queue = [];
                    this.interval = interval;
                    this.timer = null;
                    this.running = false;
                }

                addTask(task) {
                    this.queue.push(task);
                    if (!this.running) {
                        this.start();
                    }
                }

                start() {
                    if (this.running) return;
                    this.running = true;
                    this.processQueue();
                }

                processQueue() {
                    if (this.queue.length === 0) {
                        this.running = false;
                        return;
                    }

                    const task = this.queue.shift();
                    if (typeof task === 'function') {
                        try {
                            task();
                        } catch (e) {
                            console.error('Task execution error:', e);
                        }
                    }

                    this.timer = setTimeout(() => {
                        this.processQueue();
                    }, this.interval);
                }

                clear() {
                    if (this.timer) {
                        clearTimeout(this.timer);
                        this.timer = null;
                    }
                    this.queue = [];
                    this.running = false;
                }
            }

            // 创建全局任务队列实例
