				event.dialogxx=ui.create.characterDialog('heightset');
			}

			ui.create.cheat2=function(){
				ui.cheat2=ui.create.control('自由选将',function(){
					if(this.dialog==_status.event.dialog){
						if(game.changeCoin){
							game.changeCoin(50);
						}
						this.dialog.close();
						_status.event.dialog=this.backup;
						this.backup.open();
						delete this.backup;
						game.uncheck();
						game.check();
						if(ui.cheat){
							ui.cheat.animate('controlpressdownx',500);
							ui.cheat.classList.remove('disabled');
						}
					}
					else{
						if(game.changeCoin){
							game.changeCoin(-10);
						}
						this.backup=_status.event.dialog;
						_status.event.dialog.close();
						_status.event.dialog=_status.event.parent.dialogxx;
						this.dialog=_status.event.dialog;
						this.dialog.open();
						game.uncheck();
						game.check();
						if(ui.cheat){
							ui.cheat.classList.add('disabled');
						}
					}
				});
				if(lib.onfree){
					ui.cheat2.classList.add('disabled');
				}
			}
			if(!_status.brawl||!_status.brawl.chooseCharacterFixed){
				if(!ui.cheat&&get.config('change_choice'))
				ui.create.cheat();
				if(!ui.cheat2&&get.config('free_choose'))
				ui.create.cheat2();
			}
			"step 1"
			if(ui.cheat){
				ui.cheat.close();
				delete ui.cheat;
			}
			if(ui.cheat2){
				ui.cheat2.close();
				delete ui.cheat2;
			}
			var chooseGroup=false;
			if(event.chosen.length){
				if(lib.character[event.chosen[0]][1]=='shen'){
					chooseGroup=true;
				}
			}
			else if(event.modchosen){
				if(event.modchosen[0]=='random') event.modchosen[0]=result.buttons[0].link;
				else event.modchosen[1]=result.buttons[0].link;
			}
			else if(result.buttons.length==2){
				event.choosed=[result.buttons[0].link,result.buttons[1].link];
				game.addRecentCharacter(result.buttons[0].link,result.buttons[1].link);
				if(lib.character[event.choosed[0]][1]=='shen'){
					chooseGroup=true;
				}
			}
			else{
				event.choosed=[result.buttons[0].link];
				if(lib.character[event.choosed[0]][1]=='shen'){
					chooseGroup=true;
				}
				game.addRecentCharacter(result.buttons[0].link);
			}
			"step 2"
			if(event.chosen.length){
				game.me.init(event.chosen[0],event.chosen[1]);
			}
			else if(event.modchosen){
				game.me.init(event.modchosen[0],event.modchosen[1]);
			}
			else if(event.choosed.length==2){
				game.me.init(event.choosed[0],event.choosed[1]);
			}
			else{
				game.me.init(event.choosed[0]);
			}
			event.list.remove(get.sourceCharacter(game.me.name1));
			event.list.remove(get.sourceCharacter(game.me.name2));
			if(game.me==game.zhu){
				game.me.hp++;
				game.me.maxHp++;
				game.me.update();
			}

			for(var i=0;i<game.players.length;i++){
				if(game.players[i]!=game.me){
					event.list.randomSort();
					event.ai(game.players[i],event.list.splice(0,get.config('choice_'+game.players[i].identity)),null,event.list)
				}
			}
			"step 3"
			for(var i=0;i<game.players.length;i++){
				_status.characterlist.remove(game.players[i].name1);
				_status.characterlist.remove(game.players[i].name2);
			}
			setTimeout(function(){
				ui.arena.classList.remove('choose-character');
			},500);

		});
	};
}
