game.import("extension", function (lib, game, ui, get, ai, _status) {

	if(lib.config.extension_更新保护_autoAddExts) game.getFileList('extension',function(folders,files){
    if(!lib||!lib.config) return;
    var exts=lib.config.extensions;
    allFoldersExt=[];
    var plays=['coin','boss','wuxing','cardpile'];
    var addExtStr='';
    for(var i=0;i<folders.length;i++) {
        var es=folders[i];
        if(exts.contains(es)||plays.contains(es)||es=='SJ Settings') {
            continue;
        }
        allFoldersExt.add(es);
        //exts.add(es);
    }
    var addNext=function(next){
        game.getFileList('extension/'+next,function(folders2,files2){
            //alert(next+':'+files2);
            if(files2.contains('extension.js')) {
                addExtStr+='、'+next;
                exts.add(next);
                if(lib.config.extensions) lib.config.extensions.add(next);
				game.saveConfig('extension_'+next+'_enable',true);
            }
            if(allFoldersExt.length) {
                addNext(allFoldersExt.shift());
            }else if(addExtStr!='') {
                game.saveConfig('extensions',exts);
                var message='已识别扩展：'+addExtStr.slice(1)+'。请重新加载游戏！';
                var tips=function() {
				    navigator.notification.confirm(
						message,
						function(index){
							switch(index){
							    case 0:
							    tips();
							    break;
							    case 1:
							    game.reload3(true);
						    }
				    	},
			    		'三国杀·琉璃版',
	    				['载入游戏']
	    			);
    			};
    			tips();
                var forbid=ui.create.div(ui.window);
				game.createCss(`.forbid_window{
				    width: 100%;
				    height: 100%;
				    left: 0;
				    top: 0;
				    z-index: 1000000;
				}`);
				forbid.classList.add('forbid_window');
            }
        });
    }
    if(allFoldersExt.length) addNext(allFoldersExt.shift());
    //game.saveConfig('extensions',exts);
    });
	/*if (!game.getExtensionConfig('更新保护', 'incompatibleExtension') && (game.getExtensionConfig('概念武将', 'enable') || game.getExtensionConfig('假装无敌', 'enable'))) {
		alert('「更新保护」扩展提示您：\r\n安装【概念武将】和【假装无敌】扩展后，本扩展出现任何bug后果自负');
		game.saveExtensionConfig('更新保护', 'incompatibleExtension', true);
	}*/

	/**
	 * 创建fetch连接
	 * @param { string } url 资源请求地址
	 * @param { fetchOptions } options 配置
	 * @returns { Promise<Response> }
	 */
	function myFetch(url, options = { timeout: typeof game.getExtensionConfig('更新保护', 'timeout') == 'number' ? game.getExtensionConfig('更新保护', 'timeout') : 3000 }) {
		return new Promise((resolve, reject) => {
			/** @type { AbortController | undefined } */
			let myAbortController;
			/** @type { AbortSignal | undefined } */
			let signal = undefined;

			if (typeof window.AbortController == 'function') {
				if (options.timeout > 0) {
					myAbortController = new AbortController();
					signal = myAbortController.signal;
					// @ts-ignore
					setTimeout(() => myAbortController.abort(), options.timeout);
				}
			} else {
				console.warn('设备不支持AbortController');
			}

			fetch(url, { signal }).then(response => {
				if (!response.ok) {
					return reject(response);
				}
				resolve(response);
			}).catch(reject);
		});
	};

	/**
	 * 判断是否能进行更新(即是否能连接上百度)
	 * @returns { Promise<number | void> }
	 */
	function canUpdate() {
	    return true;
		/*return new Promise((resolve, reject) => {
			myFetch(`https://www.baidu.com?date=${(new Date()).getTime()}`).then(response => {
				// 304: 自上次访问以来，请求的资源未被修改
				if (response.status == 200 || response.status == 304) {
					console.log('连接百度成功，状态码: ' + response.status);
					resolve();
				} else {
					reject(response.status);
				}
			}).catch(err => reject(err));
		});*/
	}

	/**
	 * 字节转kb,mb等
	 * @param { number } limit 
	 */
	function parseSize(limit) {
		let size = "";
		if (limit < 1 * 1024) {
			// 小于1KB，则转化成B
			size = limit.toFixed(2) + "B"
		} else if (limit < 1 * 1024 * 1024) {
			// 小于1MB，则转化成KB
			size = (limit / 1024).toFixed(2) + "KB"
		} else if (limit < 1 * 1024 * 1024 * 1024) {
			// 小于1GB，则转化成MB
			size = (limit / (1024 * 1024)).toFixed(2) + "MB"
		} else {
			// 其他转化成GB
			size = (limit / (1024 * 1024 * 1024)).toFixed(2) + "GB"
		}

		// 转成字符串
		let sizeStr = size + "";
		// 获取小数点处的索引
		let index = sizeStr.indexOf(".");
		// 获取小数点后两位的值
		let dou = sizeStr.slice(index + 1, 2);
		// 判断后两位是否为00，如果是则删除00
		if (dou == "00") {
			return sizeStr.slice(0, index) + sizeStr.slice(index + 3, 2);
		}
		return size;
	};

	const assetConfigFun = function (configName) {
		return function (bool) {
			game.saveExtensionConfig('更新保护', configName, bool);
		}
	};

	/**
	 * @description 请求错误处理
	 * @param { { url: string, error: number | Error, message: string } | Error | String } err 
	 */
	const response_catch = err => {
		console.error(err);
		game.print(err);
		if (typeof err === 'object' && !(err instanceof Error)) {
			const { url, error, message } = err;
			if (typeof url !== 'undefined' && typeof error !== 'undefined' && typeof message !== 'undefined') {
				const translate = {
					coding: 'Coding',
					github: 'GitHub',
					fastgit: 'GitHub镜像',
					xuanwu: '玄武镜像'
				};
				let url_in_updateURLS;
				for (const updateURL in lib.updateURLS) {
					if (url.startsWith(lib.updateURLS[updateURL])) {
						url_in_updateURLS = translate[updateURL];
						break;
					}
				}
				if (url_in_updateURLS) {
					alert(`更新源:${url_in_updateURLS}\n网络请求目标：${url.replace(lib.updateURL + '/master/', '')}\n${error instanceof window.ProgressEvent ? '' : ('状态消息或状态码：' + error + '\n')}提示:${message}`);
				} else {
					alert(`网络请求目标：${url}\n${error instanceof window.ProgressEvent ? '' : ('状态消息或状态码：' + error + '\n')}提示:${message}`);
				}
			}
		} else if (err instanceof Error) {
			if (err.name === 'AbortError') {
				alert('网络连接超时');
			} else if (err.message == 'Failed to fetch') {
				alert('网络请求失败');
			}
		} else if (typeof err == 'string') {
			alert(err);
		}

		if (++game.updateErrors > 5) {
			//alert('检测到获取更新失败次数过多，建议您更换无名杀的更新源');
			game.updateErrors = 0;
		}
	};

	return {
		name: "更新保护",
		editable: false,
		onremove: function () {
			// 删除本扩展后，更新源改回coding
			lib.updateURL = lib.updateURLS.coding;
			game.saveConfig('update_link', 'coding');
			// 取消监听
			window.removeEventListener('beforeunload', window.saveBrokenFile);
		},
		content: function (config, pack) {
			// 替换无名杀自带的更新功能
			// 取消复选框和扩展的绑定
			const { checkForUpdate, checkForAssetUpdate } = this[4].code.config;

			/** @type HTMLButtonElement */
			let updateButton;
			/** @type HTMLButtonElement */
			let assetUpdateButton;

			const interval = setInterval(() => {
				if (typeof game.download != 'function' || typeof game.writeFile != 'function') return clearInterval(interval);
				if (!ui.menuContainer || !ui.menuContainer.firstElementChild) return;
				const menu = ui.menuContainer.firstElementChild;
				/** @type HTMLDivElement[] */
				// @ts-ignore
				const active = [...menu.querySelectorAll('.active')];
				if (active.length < 2) return;
				if (active[0].innerText != '其它' || active[1].innerText != '更新') return;
				/** @type Element */
				// @ts-ignore
				const help = menu.querySelector('.menu-help');
				const liArray = Array.from(help.querySelectorAll('li'));
				if (!liArray.length) return;

				try {
					// @ts-ignore
					updateButton = liArray[0].childNodes[1].firstElementChild;
					// @ts-ignore
					assetUpdateButton = liArray[1].childNodes[1].firstElementChild;
				} catch (error) {
					console.log("获取按钮异常：", {
						error,
						liArray,
						updateButton,
						assetUpdateButton
					});
					clearInterval(interval);					
					return;
					return alert('「更新保护」扩展提示您：\r\n获取按钮异常,覆盖游戏更新操作失败');
				}

				if (
					updateButton && updateButton.innerText == "检查游戏更新"
					&&
					assetUpdateButton && assetUpdateButton.innerText == "检查素材更新"
				) {
					updateButton.onclick = checkForUpdate.onclick.bind(updateButton);
					assetUpdateButton.onclick = checkForAssetUpdate.onclick.bind(assetUpdateButton);
				} else {
					console.log("获取按钮异常：", {
						liArray,
						updateButton,
						assetUpdateButton
					});
					clearInterval(interval);
					return;
					return alert('「更新保护」扩展提示您：\r\n获取按钮异常,覆盖游戏更新操作失败');
				}

				// 插入一条修改说明
				const ul = help.querySelector('ul');
				/** @type HTMLUListElement  */
				// @ts-ignore
				const insertWeb = ul.insertBefore(document.createElement('div'), ul.firstElementChild);
				//insertLi.innerHTML = "<span class='bluetext'>更新功能已由「更新保护」扩展覆盖</span></br>";
				insertWeb.innerHTML = '<span style="opacity:0.7;font-size:15px">Webview版本 - '+getChromeVersion()+'</span></p>';
				const insertVS = ul.insertBefore(document.createElement('li'), ul.firstElementChild);
				//insertLi.innerHTML = "<span class='bluetext'>更新功能已由「更新保护」扩展覆盖</span></br>";
				insertVS.innerHTML = '整合版本：Ver '+window.liulikillVersion+'<p style="margin-top:8px;white-space:nowrap">';
				const insertNo = ul.insertBefore(document.createElement('div'), ul.firstElementChild);
				//insertLi.innerHTML = "<span class='bluetext'>更新功能已由「更新保护」扩展覆盖</span></br>";
				insertNo.innerHTML = '<span style="opacity:0.7;font-size:15px">请勿替换或更新游戏本体！</span></p>';
				const insertLi = ul.insertBefore(document.createElement('li'), ul.firstElementChild);
				//insertLi.innerHTML = "<span class='bluetext'>更新功能已由「更新保护」扩展覆盖</span></br>";
				insertLi.innerHTML = '三国杀·琉璃版';
				// a标签跳转到扩展界面
				const jumpToExt = document.createElement('a');
				jumpToExt.href = "javascript:void(0)";
				jumpToExt.onclick = () => ui.click.extensionTab('更新保护');

				/*HTMLDivElement.prototype.css.call(jumpToExt, {
					color: 'white',
					innerHTML: '点击跳转至扩展界面'
				});

				insertLi.appendChild(jumpToExt);*/

				clearInterval(interval);
				/*console.log("「更新保护」扩展已修改更新界面");*/
			}, 500);

			// 重启前下载失败的文件名(去除重复的)
			if (!Array.isArray(lib.config.extension_更新保护_brokenFile)) {
				game.saveExtensionConfig('更新保护', 'brokenFile', []);
			} else {
				game.saveExtensionConfig('更新保护', 'brokenFile', Array.from(new Set([...lib.config.extension_更新保护_brokenFile])));
			}

			// 如果有没下载完就重启的文件
			let brokenFileArr = lib.config.extension_更新保护_brokenFile;
			window.saveBrokenFile = () => {
				game.saveExtensionConfig('更新保护', 'brokenFile', [...new Set(brokenFileArr)]);
			};
			window.addEventListener('beforeunload', window.saveBrokenFile);
			if (brokenFileArr && brokenFileArr.length) {
				// 改为用setTimeout，因为刚开启时候的网络请求不会成功
				setTimeout(() => {
					if (confirm(`检测到有未下载成功的文件(${brokenFileArr})，是否进行重新下载?`)) {
						console.log('未下载成功的文件：', brokenFileArr);
						// 复制文件数组，用来和进度绑定
						const copyList = [...brokenFileArr];
						// 当前下载进度
						let index = 0;
						// 创建下载进度div
						const progress = game.shijianCreateProgress('重新下载', copyList.length, copyList[0], index);
						document.body.appendChild(progress);
						// 下载之前保留下载列表
						brokenFileArr.forEach(v => lib.config.extension_更新保护_brokenFile.add(v));
						game.saveConfigValue('extension_更新保护_brokenFile');
						game.shijianMultiDownload(brokenFileArr, () => {
							// 下载成功，更新进度
							progress.setProgressValue(++index);
							progress.setFileName(copyList[index]);
						}, (err, message) => {
							// 下载失败
							if (message == '用户未登录') {
								// 移除进度条
								progress.remove();
								// 延时提示
								setTimeout(() => {
									alert('错误: 用户未登录(用coding和玄武镜像可能会出现此问题)\n请更换成其他更新源');
								}, 100);
							}
						}, () => {
							// 下载完成 不执行onsuccess而是onfinish
							progress.setProgressValue(copyList.length);
							progress.setFileName('下载完成');
							setTimeout(() => {
								// 移除进度条
								progress.remove();
								// 延时提示
								setTimeout(() => {
									alert('下载完成，将自动重启');
									game.reload();
								}, 100);
							}, 200);
						}, (current, loaded, total) => {
							if (total != 0) {
								progress.setFileName(`${current}(已完成${Math.round((loaded / total) * 100)}%)`);
							} else {
								progress.setFileName(`${current}(已下载${parseSize(loaded)})`);
							}
						});
					} else {
						console.log('不进行重新下载，已清空失败列表');
						brokenFileArr.length = 0;
						game.saveConfigValue('extension_更新保护_brokenFile');
					}
				}, 2500);
			}

			// 切换回应用，清除app通知
			if (game.shijianHasLocalNotification()) {
				document.addEventListener('visibilitychange', () => {
					if (!document.hidden) {
						// 检查更新
						cordova.plugins.notification.local.clear(1);
						// 游戏版本更新完成
						cordova.plugins.notification.local.clear(4);
						// 游戏素材更新完成
						cordova.plugins.notification.local.clear(5);
					}
				});
			}

			// 自动检测更新
			function checkUpdate() {
				game.shijianGetUpdateFiles().then(({ update }) => {
					console.log('获取到更新', update);
					if (update.version == lib.version) {
						return;
					} else {
						/** 现有版本 */
						let v1 = lib.version.split('.').map(item => Number(item) || 0);
						/** 服务器版本 */
						let v2 = update.version.split('.').map(item => Number(item) || 0);
						for (let i = 0; i < v1.length && i < v2.length; i++) {
							v1[i] = v1[i] || 0;
							v2[i] = v2[i] || 0;
							if (v2[i] > v1[i]) break;
							// 游戏版本比服务器提供的版本还要高
							if (v1[i] > v2[i]) {
								return;
							}
						}
					}

					function goupdate() {
						ui.menuContainer.show();
						ui.click.extensionTab('更新保护');
						/** @type { HTMLButtonElement[] } */
						// @ts-ignore
						const buttonList = ui.menuContainer.querySelectorAll('.config>span>button');
						const updateButton = buttonList[0];
						const assetUpdateButton = buttonList[1];
						if (updateButton && assetUpdateButton) {
							updateButton.click();
							assetUpdateButton.click();
						} else {
							alert('「更新保护」扩展提示您：\r\n未找到本扩展的更新按钮，请手动点击检查游戏更新和素材更新');
						}
					}

					// 获取到更新，进行提示
					let str = '有新版本' + update.version + '可用，是否前往「更新保护」扩展界面下载？';

					// 处于后台时，发送通知
					if (game.shijianHasLocalNotification()) {
						if (document.hidden) {
							let str2 = update.changeLog[0];
							for (let i = 1; i < update.changeLog.length; i++) {
								if (update.changeLog[i].indexOf('://') == -1) {
									str2 += '；' + update.changeLog[i];
								}
							}
							cordova.plugins.notification.local.schedule({
								id: 1,
								title: '更新提醒',
								text: str + '\n' + str2,
							});
						}
					}

					if (navigator.notification && navigator.notification.confirm) {
						let str2 = update.changeLog[0];
						for (let i = 1; i < update.changeLog.length; i++) {
							if (update.changeLog[i].indexOf('://') == -1) {
								str2 += '；' + update.changeLog[i];
							}
						}
						navigator.notification.confirm(str2, index => {
							if (index == 1) goupdate();
						},
							str,
							['确定', '取消']
						);
					} else {
						if (confirm(str)) {
							goupdate();
