                                if (!node.classList.contains('moved')) {
                                    event.blank.push(node.index);
                                }
                                if (i > event.config.width * 2 && node.classList.contains("hiddenAvatar")) {
                                    node.classList.remove("hiddenAvatar");
                                    lib.setIntro(node);
                                } 
                                event.nodes[node.index].style.display = '';
