                                    for (var i = 0; i < event.friendlist.length; i++) {
                                        event.friendlist[i].style.transform = 'scale(1.2) translate(' + (-(event.width + 14) * event.friendlist.length / 2 + 7 + i * (event.width + 14)) + str;
                                    }
                                }
                                else {
