                        if (!avatar) return
                        player.dynamic.renderer.postMessage({
                            message: 'CHANGE_ACTION',
                            id: player.dynamic.id,
                            skinInfo,
                            isDefault,  // 标明是否返回默认的待机状态
                            skinID: avatar.id,
