                                //         newImg.style.position = 'absolute'
                                //         newImg.style.top = '500px'
                                //
                                //     });
                                // }, 2000)
                            }

                            if (dy.hasSpine(filename)) {
                                play()
                            } else {
                                dy.loadSpine(filename, ext, () => {
                                    play()
                                }, (err, err2) => {
                                    console.log('加载骨骼错误', err, err2)
                                    let errMsg = ''
                                    if (err2 && err2.indexOf('atlas page image') !== -1) {
