                            setTimeout(() => {
                                if (lastSelFile) {
                                    for (let idx = 0; idx < filesEle.children.length; idx++) {
                                        if (lastSelFile === filesEle.children[idx]) {
                                            if (idx > 5) {
                                                filesEle.parentNode.scrollTop = 40 * (idx - 5)
                                            }
