                        // 选择静皮还原
                        let dynamicSkinKey = skinSwitch.configKey.dynamicSkin
                        if (!lib.config[dynamicSkinKey]) lib.config[dynamicSkinKey] = {}
                        lib.config[dynamicSkinKey][name] = 'none'
                        game.saveConfig(dynamicSkinKey, lib.config[dynamicSkinKey]);
