                                    x: [0, 0.65],
                                    y: [0, 0.5],
                                    name: filename,
                                    scale: 0.5,
                                    loop: true
                                }
                                let isPreviewed = false
                                if (filename in skinSwitch.nodePreviewedInfo) {
