                        scrollbox.update()
                        window.preBox = scrollbox
                        const dragDiv = ui.create.div('.drag-div')
                        dragDiv.style.width = scrollbox.boxWidth + 'px'
                        dragDiv.style.height = scrollbox.boxHeight * 1.8 + 'px'
