Matrix4.prototype.translate = function (x, y, z) {
				var v = this.values;
				v[12] += v[0] * x + v[4] * y + v[8]  * z;
				v[13] += v[1] * x + v[5] * y + v[9]  * z;
				v[14] += v[2] * x + v[6] * y + v[10] * z;
				v[15] += v[3] * x + v[7] * y + v[11] * z;
				return this;
			}

