            game.isExt = function(path, callback) {
                if (lib.node && lib.node.fs) {
                    try {
                        var stat = lib.node.fs.statSync(__dirname + '/' + path);
                        callback(stat);
                    } catch(e) {
                        callback(false);
                        return;
                    }
                } else {
                    resolveLocalFileSystemURL(lib.assetURL + path, (function(name) {
                        return function(entry) {
                            callback(true);
                        }
                    } (name)),
                    function() {
                        callback(false);
                    });
                }
            };
