                    var tps = ['none', 'from', 'to', 'self'];
                    var num = 0;
                    if (event.from == player || event.to.contains(player)) {
                        //仅对于自己和对象
                        event.ide = 'me';
                        if (player == event.from) num++;
                        if (event.to.contains(player)) num += 2;
                    } else {
                        //优先发起者，再判断目标
                        event.ide = 'see';
                        if (event.from != 'none' && get.attitude(player, event.from) > 0) num++;
