                        if(get.config('double_character')&&lib.config.forbiddouble.contains(i)) continue;
                        var skills=characterPack[i][3];
                        //要ban的技能
                        var banskills=['sbzhangwu','xinfu_tunjun'];
                        for(var a=0;a<skills.length;a++) {
