                    //alert(files);
                    if(files){
                        lib.chkcad[him]=files;
                        //return files;
                    }else {
                        lib.chkcad[him]=false;
                        //return false;
                    }
                    return game.cadpic;
                });
            }else {
                lib.chkcad[him]=false;
            }
            return;
        });
        return;
    };
    game.folderExt=function(fs){
