        var timerun=function (num,add,zuanspeed,width,height,sp,png,wwid) {
            if(game.phshow) game.phshow.remove();
            var wait=0;
            var adds=add;
            if(adds==1) {
                var left=0*wwid*0.31*sp-(10*zuanspeed-num)*(10*zuanspeed-num)*wwid*0.0025*sp/zuanspeed;
                var plus=1;
                if(num<10*zuanspeed) {
