lib.skill.quanji = {
    audio:2,
    trigger:{
        player:"damageEnd",
    },
    frequent:true,
    locked:false,
    notemp:true,
    filter:function(event){
        return event.num>0;
    },
    content:function(){
        "step 0"
        event.count=trigger.num;
        "step 1"
        event.count--;
        player.draw();
        "step 2"
        if(player.countCards('h')){
            player.chooseCard('将一张手牌置于武将牌上作为“权”',true);
        }
        else{
            event.goto(4);
        }
        "step 3"
        if(result.cards&&result.cards.length){
            player.addToExpansion(result.cards,player,'giveAuto').gaintag.add('quanji');
        }
        "step 4"
        if(event.count>0&&player.hasSkill('quanji')){
            player.chooseBool(get.prompt2('quanji')).set('frequentSkill','quanji');
        }
        else event.finish();
        "step 5"
        if(result.bool){
            player.logSkill('quanji');
            event.goto(1);
        }
    },    
    marktext:"权",
    intro:{
        // content:"expansion",
         markcount:"expansion",
                mark:function(dialog,storage,player){     
                    chakangpaiming('权计',player.getExpansions('quanji'),true);	
            },                   
    },
    onremove:function(player,skill){
        var cards=player.getExpansions(skill);
        if(cards.length) player.loseToDiscardpile(cards);
    },
    mod:{
        maxHandcard:function(player,num){
            return num+player.getExpansions('quanji').length;
        },
    },
    ai:{
        maixie:true,
        "maixie_hp":true,
        threaten:0.8,
        effect:{
            target:function(card,player,target){
                if(get.tag(card,'damage')){
                    if(player.hasSkillTag('jueqing',false,target)) return [1,-2];
                    if(!target.hasFriend()) return;
                    if(target.hp>=4) return [0.5,get.tag(card,'damage')*2];
                    if(!target.hasSkill('paiyi')&&target.hp>1) return [0.5,get.tag(card,'damage')*1.5];
                    if(target.hp==3) return [0.5,get.tag(card,'damage')*1.5];
                    if(target.hp==2) return [1,get.tag(card,'damage')*0.5];
                }
            },
        },
    },
}
