                  let distance = (100 - Math.sqrt(Math.pow(Math.abs(zhengjingMouse[i + 1].x - zhengjingMouse[i].x), 2) + Math.pow(Math.abs(zhengjingMouse[i + 1].y - zhengjingMouse[i].y), 2))) * 0.076;
                  distance = Math.min(10, distance);
