            function addCardName(str) {
              ctx.fillStyle = "#e7e2c2";
              var fontX, fontY;
              var newLine = false;
              switch (str.length) {
                case 1: {
                  ctx.font = '49px "th-zhongli"';
                  fontX = -24;
                  fontY = 11;
                  break;
                }
                case 2: {
                  ctx.font = '34px "th-zhongli"';
