                  break;
                }
                default: {
                  ctx.font = '24px "th-zhongli"';
                  fontX = -24;
                  fontY = -9;
                  newLine = true;
                }
              }
              if (newLine) {
                ctx.fillText(str.slice(0, 2), fontX, fontY);
                if (str.length == 4) ctx.fillText(str.slice(2), fontX, fontY + 26);
                else ctx.fillText(str.slice(2), fontX - 12, fontY + 23);
