                  var type = get.itemtype(cards);
                  if (type != 'cards') {
                    if (type != 'card')
                      return;

                    type = 'cards';
                    cards = [cards];
                  }

                  game.broadcast(function (cards) {
                    $thunderGain2(cards);
                  }, cards);

                  var gains = [];
                  var draws = [];

                  var card;
                  var clone;
                  for (var i = 0; i < cards.length; i++) {
                    clone = cards[i].clone;
                    card = cards[i].copy('thrown', 'gainingcard');
                    card.fixed = true;
                    if (clone && clone.parentNode == ui.arena) {
                      card.scaled = true;
                      card.style.transform = clone.style.transform;
                      gains.push(card);
                    } else {
                      draws.push(card);
