registrations.source:
game.import('mode',function(lib,game,ui,get,ai,_status){
	return {
		name:'boss',
		start:function(){
			"step 0"
			var playback=localStorage.getItem(lib.configprefix+'playback');
			if(playback){
				ui.create.me();
				ui.arena.style.display='none';
				ui.system.style.display='none';
				_status.playback=playback;
				localStorage.removeItem(lib.configprefix+'playback');
				var store=lib.db.transaction(['video'],'readwrite').objectStore('video');
				store.get(parseInt(playback)).onsuccess=function(e){
					if(e.target.result){
						game.playVideoContent(e.target.result.video);
					}
					else{
						alert('播放失败：找不到录像');
						game.reload();
					}
				}
				event.finish();
				return;
			}
			for(var i in lib.characterPack.mode_boss){
				lib.character[i]=lib.characterPack.mode_boss[i];
				if(!lib.character[i][4]){
					lib.character[i][4]=[];
				}
			}
			// for(var i in lib.cardPack.mode_boss){
			//		lib.card[i]=lib.cardPack.mode_boss[i];
			// }
			for(var i in lib.skill){
				if(lib.skill[i].changeSeat){
					lib.skill[i]={};
					if(lib.translate[i+'_info']){
						lib.translate[i+'_info']='此模式下不可用';
					}
				}
			}
			lib.translate.restart='返回';
			lib.init.css(lib.assetURL+'layout/mode','boss');
			game.delay(0.1);
			"step 1"
			window.addGoldFont=function(str,add){
                if(!add) add='';
                return '<span style="'+add+'background-image: linear-gradient(180deg, #f0d775 30%, #ab8c31 57%, #b0a04d 67%);	font-weight:bold; -webkit-background-clip: text; -webkit-text-fill-color: transparent; white-space: nowrap; -webkit-text-stroke: 0px rgba(38,37,34,0.5); text-shadow: none;">'+str+'</span>';
            }
			var bosslist=ui.create.div('#bosslist.hidden');
			event.bosslist=bosslist;
			lib.setScroll(bosslist);
			var noScroll=true;
			bosslist.isRolling=false;
			bosslist.isRollingM=false;
			var scrollToS=function(to,last,me) {
			    if(noScroll) return;
			    if(!get.config('selectbs_move')) return;
			    if(bosslist.isRollingM) return;
			    if(event.current!=me) return;
			    //return scrollToQ(to);
			    //感谢lyl大神教的多线程异步大法
			    return new Promise((resolve)=>{
			    var left=bosslist.scrollLeft;
			    var dis=to-left;
			    if(Math.abs(dis)<3||last==left) {
			        bosslist.isRolling=false;
			        //bosslist.style.pointerEvents='auto';
			        bosslist.scrollTo(to,0);
			    }else {
			        bosslist.isRolling=true;
			        //bosslist.style.pointerEvents='none';
			        var turn=left+(dis/3);
			        var lastLeft=bosslist.scrollLeft;
			        bosslist.scrollTo(turn,0);
			        setTimeout(function() {
			            scrollToS(to,lastLeft,me);
			        },10);
			    }
			    });
			};
			var scrollToQ=function(to,last) {
			    if(noScroll) return;
			    if(!get.config('selectbs_move')) return;
			    bosslist.scrollTo(to,0);
			};
			var bossNodes=[];
			game.firstDragBoss=false;
			if(get.config('selectbs_move')) {
			    var cheBosslistIsRoll=function(pos){
			        if(game.bossStart) return;
			        //感谢lyl大神教的多线程异步大法
			        return new Promise((resolve)=>{
			        var last=bosslist.scrollLeft;
			        if(bosslist.scrollLeft==pos) {
			            bosslist.isRolling=false;
			        }else {
			            bosslist.isRolling=true;
			        }
					if(get.config('boss_fps_access')) bossNodes.forEach(player=>{
					    player.hideMyPos();
					});
			        if(game.firstDragBoss) bossNodes.forEach(player=>{
					    player.checkMyPos();
					});
			        setTimeout(function() {
			             cheBosslistIsRoll(last);
			        },10);
			        });
			    };
			    cheBosslistIsRoll();
			    var stopRolling=false;
			    bosslist.addEventListener(lib.config.touchscreen?'touchstart':'mousedown',function(e){
					//if(!node.classList.contains('hidden')) node.classList.add('pressdown');
					bosslist.isRollingM=true;
					stopRolling=true;
				});
				bosslist.addEventListener(lib.config.touchscreen?'touchend':'mouseup',function(e){
					//node.classList.remove('pressdown');
					stopRolling=false;
					var finish=function() {
    					bosslist.isRollingM=false;
    					game.firstDragBoss=true;
    					stopRolling=false;
    					setTimeout(function() {
    					    noScroll=false;
    					},20);
					};
					var next=function(sourcePos) {
				        if(stopRolling) return;
				        setTimeout(function() {
				            if(Math.abs(sourcePos-bosslist.scrollLeft)<10) {
    					        finish();
    					        //alert('stop');
					        }else {
					            next(bosslist.scrollLeft);
					        }
				        },100);
					};
					next(bosslist.scrollLeft);
				});
				bosslist.addEventListener(lib.config.touchscreen?'touchmove':'mousemove',function(e){
					//node.classList.remove('pressdown');
					bosslist.isRollingM=true;
					stopRolling=true;
					noScroll=true;
				});
			};
			var idelist={
			    'zhu':[200,50,50],
			    'zhong':[200,200,50],
			    'nei':[150,50,250],
			    'fan':[50,200,50],
			    'wei':[50,100,200],
			    'shu':[200,200,50],
			    'wu':[50,200,50],
			    'qun':[100,100,100],
			    'jin':[150,50,250],
			};
			var banColor=function(ide) {
			    switch(ide) {
			        case 'zhu':
			        case 'shu':
			        return [190,60,60];
			        break;
			        case 'zhong':
			        case 'qun':
			        return [230,200,50];
			        break;
			        case 'fan':
			        case 'wu':
			        return [80,120,30];
			        break;
			        case 'nei':
			        case 'jin':
			        return [140,90,250];
			        break;
			        case 'wei':
			        return [80,100,140];
			        break;
			        default:
			        return [140,90,250];
			        break;
			    }
			};
			var ideColor=function(ide) {
			    var color=banColor(ide);
			    var sum=color[0]+color[1]+color[2];
			    var pec=300/sum;
			    return [color[0]*pec,color[1]*pec,color[2]*pec];
			};
			var setHighLight=function(player,hide) {
			    //var color=[140,90,255];
			    var ide=player.node.identity.dataset.color;
			    var nature=get.config('selectbs_boss');
			    if((nature=='none'||!nature)&&!hide) return;
			    if(nature!='nature') ide=nature;
			    var color=ideColor(ide);
			    var light=100;
			    var sbder=get.config('selectbs_border')|3;
			    var opacity=(sbder+5)/10;
			    var border=(sbder-3)*0.3+6;
			    var color1=Math.min(255,color[0]+light)+','+Math.min(255,color[1]+light)+','+Math.min(255,color[2]+light);
			    var color2=color.join(',');
			    if(!hide) {
			        player.kuang.style.boxShadow=`0 0 ${border/2}px ${border/2}px rgba(${color1},${opacity}),
                    0 0 ${border}px ${border}px rgba(${color2},${opacity})`;
                }else {
                    player.kuang.style.boxShadow=`0 0 0px 0px rgba(${color1},0),
                    0 0 0px 0px rgba(${color2},0)`;
                }
			}
			window.requestAnimationFrame(scrollToS);
			// bosslist.ontouchmove = ui.click.touchScroll;
			// bosslist.style.WebkitOverflowScrolling='touch';
			if(!lib.config.touchscreen&&lib.config.mousewheel){
				bosslist._scrollspeed=30;
				bosslist._scrollnum=10;
				bosslist.onmousewheel=ui.click.mousewheel;
			}
			// var bosslistlinks={};
			// var toggleBoss=function(bool){
			//		game.saveConfig(this._link.config._name,bool,true);
			//		var node=bosslistlinks[this._link.config._name];
			//		if(bool){
			//			node.style.display='';
			//		}
			//		else{
			//			node.style.display='none';
			//		}
			// };
			var onpause=function(){
				ui.window.classList.add('bosspaused');
			}
			var onresume=function(){
				ui.window.classList.remove('bosspaused');
			}
			game.onpause=onpause;
			game.onpause2=onpause;
			game.onresume=onresume;
			game.onresume2=onresume;
			ui.create.div(bosslist);
			bosslist.style.zIndex=0;
			//全能搜索关闭
            if(ui.Searcher) ui.Searcher.hide();
            if(ui.JinJiang) ui.JinJiang.hide();
            if(window.cardPicture) {
                if(window.cardPicture.cardPicture) window.cardPicture.cardPicture.hide();
                if(window.cardPicture.cardNumber) window.cardPicture.cardNumber.hide();
            }

			event.current=null;
			var list=[];
			for(var i in lib.character){
				var info=lib.character[i];
				if(info[4].contains('boss')){
					// var cfg=i+'_bossconfig';
					// if(get.config(cfg)==undefined){
					//		game.saveConfig(cfg,true,true);
					// }
					// lib.translate[cfg+'_config']=lib.translate[i];
					// lib.mode.boss.config[cfg]={
					//		name:get.translation(i),
					//		onclick:toggleBoss,
					//		init:true,
					// }
					var player=ui.create.player(bosslist).init(i);
					if(lib.characterPack.mode_boss[i]&&get.config(i+'_boss_config')==false){
						player.style.display='none';
					}
					if(player.hp==0){
						player.node.hp.style.display='none';
					}
					list.push(player);
					player.node.hp.classList.add('text');
					player.node.hp.dataset.condition='';
					player.node.hp.innerHTML=info[2];
					if(info[2]==Infinity){
						player.node.hp.innerHTML='∞';
					}
					var name=player.name;
					if(name=='boss_qinguangwang') name='十殿阎罗';
					player.setIdentity(name);
					player.node.identity.dataset.color=info[5];
					player.node.identity.style.top='25px';
					player.node.identity.style.left='5px';
					//player.node.identity=ui.create.div(player);
					player.node.identity.style.left='0';
					player.node.identity.style.top='0';
					//player.node.identity.style.backgroundColor='rgba(0,200,255,0.5)';
					player.node.identity.style.height='100%';
					player.node.identity.style.width='100%';
					player.node.identity.style.zIndex=10;
					player.node.identity.innerHTML=' ';
					player.node.identity.style.textAlign='center';
					player.bossname=ui.create.div(player.node.identity);
					player.bossname.innerHTML=get.translation(name);
					player.bossname.style.writingMode='vertical-rl';
					player.bossname.style.left='15%';
					player.bossname.style.top='10%';
					player.bossname.style.width='30px';
					player.bossname.style.height='160px';
					player.bossname.style.fontSize='30px';
					player.bossname.style.position='absolute';
					player.bossname.style.textAlign='left';
					//player.node.identity.style.overFlow='visible';
					// bosslistlinks[cfg]=player;
					player.classList.add('bossplayer');
					var node2=ui.create.div(player.node.avatar);
				    node2.style["background-image"]=('url("'+lib.assetURL+'image/mode/boss/demon.png")');
		            node2.style["background-position"]='0% 0%';
					node2.style["background-repeat"]='no-repeat';
					node2.style["background-size"]='100% 100%';
					node2.style["height"]='110%';
					node2.style["width"]='110%';
					node2.style["top"]='-5%';
					node2.style["left"]='-5%';
					node2.style["opacity"]='1';
					node2.style["overflow-y"]='visible !important';
					node2.style["border-radius"]='7px';
					node2.style["pointer-events"]='none';
					player.kuang=node2;
					player.nickname='挑战关卡';
					player.guanjie='boss_zhu';
					player.level='?';
					player.node.avatar.style.boxShadow='0 0 10px 7px rgba(0,0,0,1)';

					if(lib.storage.current==i){
						event.current=player;
						player.classList.add('highlight');
						/*player.kuang.style.boxShadow=`0 0 3px 3px rgba(220,170,255,1),
                        0 0 7px 7px rgba(140,90,255,1)`;*/
                        setHighLight(player);
						if(!lib.config.continue_name_boss&&lib.boss[i]&&lib.boss[i].control){
							_status.bosschoice=lib.boss[i].control();
							_status.bosschoice.name=i;
							_status.bosschoice.link=lib.boss[i].controlid||i;
						}
					}

					player.checkMyPos=function() {
					    var player=this;
					    if(!player) return;
					    if(game.bossStart) return;
					    var left=player.offsetLeft-(ui.window.offsetWidth-180)/2;
                        var dis=Math.abs(left-bosslist.scrollLeft);
                        if(dis<110&&(dis>10||event.current!=player)&&game.letMeChioce&&!bosslist.isRolling&&!bosslist.isRollingM) {
                            //player.style.opacity=1;
                            game.letMeChioce(player);
                        }
					    /*setTimeout(function() {
					        player.checkMyPos();
					    },100);*/
					}
					player.hideMyPos=function() {
					    var player=this;
					    if(!player) return;
					    if(game.bossStart) return;
					    var left=player.offsetLeft-(ui.window.offsetWidth-180)/2;
                        var dis=Math.abs(left-bosslist.scrollLeft);
                        var limited=500;
                        if(dis>limited) {
                            player.style.opacity=0;
                            player.style.visibility='hidden';
                        }else {
                            player.style.visibility='visible';
                            if(dis>limited*0.5) {
                                player.style.opacity=0.2;
                            }else {
                                player.style.opacity='';
                            }
                        }
                        //转轮特效呢！
                        if(!get.config('boss_zhuanlun')) return;
                        bosslist.style.height='600px';
                        var rot=0;
                        var dow=0;
                        var size=1;
                        var wed=0;
                        if(dis>limited) {
                            rot=70;
                            dow=240;
                            size=0.85;
                            wed=160;
                        }else if(dis>limited*0.85) {
                            rot=50;
                            dow=190;
                            size=0.9;
                            wed=130;
                        }else if(dis>limited*0.5) {
                            rot=35;
                            dow=120;
                            size=0.95;
                            wed=0;
                        }else if(dis>limited*0.25) {
                            rot=15;
                            dow=30;
                            size=1;
                            wed=-10;
                        }else {
                            rot=0;
                            dow=0;
                            size=1.1;
                            wed=0;
                        }
                        if(left<bosslist.scrollLeft) {
                            rot*=-1;
                            wed*=-1;
                        }
                        player.style.transition='all 0.3s ease';
                        player.style.transform='rotate('+rot+'deg) translateY('+dow+'px) translateX('+wed+'px) scale('+size+')';
					}
					if(!get.config('unselectbs_blur')) player.classList.add('bossplayern');
					bossNodes.push(player);
					//if(get.config('selectbs_move')) player.checkMyPos();

					// if(!get.config(cfg)){
					//		player.style.display='none';
					// }
				}
			}
			if(!list.length){
				alert('没有可挑战的BOSS');
				event.finish();
				lib.init.onfree();
				_status.over=true;
				return;
			}else if(get.config('selectbs_move')){
			    list[0].style['margin-left']=180*/*(2+0.5*1.2)*/3+'px';
			    list[list.length-1].style['margin-right']=180*/*(2+0.5*1.2)*/3+'px';
			}
			if(!event.current){
				event.current=bosslist.childNodes[1];
				event.current.classList.add('highlight');
				/*event.current.kuang.style.boxShadow=`0 0 3px 3px rgba(220,170,255,1),
                    0 0 7px 7px rgba(140,90,255,1)`;*/
                setHighLight(event.current);
			}
			ui.create.div(bosslist);
			ui.create.cardsAsync();
			game.finishCards();
			game.addGlobalSkill('autoswap');
			ui.arena.setNumber(8);
			ui.control.style.transitionProperty='opacity';
			ui.control.classList.add('bosslist');
			setTimeout(function(){
				ui.control.style.transitionProperty='';
			},1000);

			ui.window.appendChild(bosslist);

			setTimeout(function(){
				if(event.current){
					var left=event.current.offsetLeft-(ui.window.offsetWidth-180)/2;
					if(bosslist.scrollLeft<left){
						bosslist.scrollLeft=left;
					}
				}
				noScroll=false;
				bosslist.show();
			},200);
			game.me=ui.create.player();
			if(lib.config.continue_name_boss){
				event.noslide=true;
				lib.init.onfree();
			}
			else{
				game.chooseCharacter(function(target){
					bosslist.isRolling=false;
					bosslist.isRollingM=false;
					if(event.current){
						event.current.classList.remove('highlight');
						/*event.current.kuang.style.boxShadow=`0 0 0px 0px rgba(220,170,255,0),
                        0 0 0px 0px rgba(140,90,255,0)`;*/
                        setHighLight(event.current,true);
					}
					game.bossChangeDialog(false);
					event.current=target;
					game.save('current',target.name);
					target.classList.add('highlight');
					/*target.kuang.style.boxShadow=`0 0 3px 3px rgba(220,170,255,1),
                        0 0 7px 7px rgba(140,90,255,1)`;*/
                    setHighLight(target);
                    if(window.tipsClick) window.tipsClick('Enter');
                    var left=target.offsetLeft-(ui.window.offsetWidth-180)/2;
                    scrollToS(left,false,target);
					//这里是选完角色的
					if(_status.bosschoice){
						var name=target.name;
						if(lib.boss[target.name]&&lib.boss[target.name].controlid){
							name=lib.boss[target.name].controlid;
						}
						if(_status.bosschoice.link!=name){
							lib.boss[_status.bosschoice.name].control('cancel',_status.bosschoice);
							_status.bosschoice.classList.remove('disabled');
							_status.bosschoice.close();
							delete _status.bosschoice;
						}
						else{
							return;
						}
					}
					if(lib.boss[target.name]&&lib.boss[target.name].control){
						_status.createControl=ui.control.firstChild;
						_status.bosschoice=lib.boss[target.name].control();
						_status.bosschoice.name=target.name;
						_status.bosschoice.link=lib.boss[target.name].controlid||target.name;
						if(ui.cheat2&&ui.cheat2.dialog==_status.event.dialog){
							_status.bosschoice.classList.add('disabled');
						}
						delete _status.createControl;
					}
				});
				game.letMeChioce=function(target){
					if(event.current){
						event.current.classList.remove('highlight');
						/*event.current.kuang.style.boxShadow=`0 0 0px 0px rgba(220,170,255,0),
                        0 0 0px 0px rgba(140,90,255,0)`;*/
                        setHighLight(event.current,true);
					}
					game.bossChangeDialog(false);
					event.current=target;
					game.save('current',target.name);
					target.classList.add('highlight');
					/*target.kuang.style.boxShadow=`0 0 3px 3px rgba(220,170,255,1),
                        0 0 7px 7px rgba(140,90,255,1)`;*/
                    setHighLight(target);
                    if(window.tipsClick) window.tipsClick('Enter');
                    var left=target.offsetLeft-(ui.window.offsetWidth-180)/2;
                    scrollToS(left,false,target);
					//这里是选完角色的
					if(_status.bosschoice){
						var name=target.name;
						if(lib.boss[target.name]&&lib.boss[target.name].controlid){
							name=lib.boss[target.name].controlid;
						}
						if(_status.bosschoice.link!=name){
							lib.boss[_status.bosschoice.name].control('cancel',_status.bosschoice);
							_status.bosschoice.classList.remove('disabled');
							_status.bosschoice.close();
							delete _status.bosschoice;
						}
						else{
							return;
						}
					}
					if(lib.boss[target.name]&&lib.boss[target.name].control){
						_status.createControl=ui.control.firstChild;
						_status.bosschoice=lib.boss[target.name].control();
						_status.bosschoice.name=target.name;
						_status.bosschoice.link=lib.boss[target.name].controlid||target.name;
						if(ui.cheat2&&ui.cheat2.dialog==_status.event.dialog){
							_status.bosschoice.classList.add('disabled');
						}
						delete _status.createControl;
					}
				};
			}
			if(lib.config.test_game){
				event.current.classList.remove('highlight');
				/*event.current.kuang.style.boxShadow=`0 0 0px 0px rgba(220,170,255,0),
                        0 0 0px 0px rgba(140,90,255,0)`;*/
                setHighLight(event.current,true);
				if(event.current.nextSibling&&event.current.nextSibling.classList.contains('player')){
					event.current=event.current.nextSibling;
				}
				else{
					event.current=event.current.parentNode.childNodes[1];
				}
				game.save('current',event.current.name);
			}
			"step 2"
			game.bossinfo=lib.boss.global;
			for(var i in lib.boss[event.current.name]){
				game.bossinfo[i]=lib.boss[event.current.name][i];
			}

			setTimeout(function(){
				ui.control.classList.remove('bosslist');
			},500);
			var boss=ui.create.player();
			boss.getId();
			game.boss=boss;
			boss.init(event.current.name);
			boss.side=true;
			if(!event.noslide){
				var rect=event.current.getBoundingClientRect();
				boss.animate('bossing');
				boss.node.hp.animate('start');
				boss.bossinginfo=[rect.left+rect.width/2,rect.top+rect.height/2];
				boss.style.transition='all 0s';
				boss.node.equips.style.opacity='0';
			}
			else{
				boss.animate('start');
			}
			boss.setIdentity('zhu');
			boss.identity='zhu';
			if(lib.config.continue_name_boss){
				result=lib.config.continue_name_boss;
				game.saveConfig('continue_name_boss');
			}
			for(var i=0;i<result.links.length;i++){
				var player=ui.create.player();
				player.getId();
				player.init(result.links[i]).animate('start');
				player.setIdentity('cai');
				player.identity='cai';
				player.side=false;
				game.players.push(player);
				if(result.boss){
					if(game.bossinfo.minion){
						player.dataset.position=i+3;
					}
					else{
						player.dataset.position=(i+1)*2;
					}
				}
				else{
					player.dataset.position=i+1;
				}
				ui.arena.appendChild(player);
			}
			if(result.boss){
				game.players.unshift(boss);
				boss.dataset.position=0;
			}
			else{
				game.players.push(boss);
				boss.dataset.position=7;
			}
			if(game.bossinfo.minion){
				if(!result.boss){
					boss.dataset.position=6;
				}
				for(var i in game.bossinfo.minion){
					var player=ui.create.player();
					player.getId();
					player.init(game.bossinfo.minion[i]);
					if(boss.bossinginfo){
						player.animate('bossing');
						player.node.hp.animate('start');
						player.style.transition='all 0s';
					}
					else{
						player.animate('start');
					}
					player.setIdentity('zhong');
					player.identity='zhong';
					player.side=true;
					game.players.push(player);
					var num=parseInt(i);
					if(result.boss){
						player.dataset.position=num-1;
					}
					else{
						if(num==2){
							player.dataset.position=7;
						}
						else{
							player.dataset.position=num-3;
						}
					}
					ui.arena.appendChild(player);
					if(boss.bossinginfo){
						var rect=player.getBoundingClientRect();
						player.style.transform='translate('+(boss.bossinginfo[0]-rect.left-rect.width/2)+'px,'+(boss.bossinginfo[1]-rect.top-rect.height/2)+'px) scale(1.1)';
						ui.refresh(player);
						player.style.transition='';
						player.style.transform='';
					}
				}
			}
